import type { Bed, Floor, FloorNumber, Room } from "@/types";

/**
 * OFFICIAL room numbering — explicit, never generated by a sequence.
 * Order of each array is geographic: index 0 = WEST end, last index = EAST end.
 */
export const OFFICIAL_ROOM_NUMBERS: Record<FloorNumber, readonly number[]> = {
  1: [100, 101, 102, 103, 104, 105, 106, 107, 108, 109],
  2: [201, 202, 203, 204, 205, 206, 207, 208, 209, 210],
  3: [301, 302, 303, 304, 305, 306, 307, 308, 309, 310],
};

export const BED_LABELS = ["A", "B", "C", "D"] as const;

export const FLOORS: Floor[] = [
  { id: "floor-1", number: 1, nameEn: "First Floor", nameBn: "প্রথম তলা" },
  { id: "floor-2", number: 2, nameEn: "Second Floor", nameBn: "দ্বিতীয় তলা" },
  { id: "floor-3", number: 3, nameEn: "Third Floor", nameBn: "তৃতীয় তলা" },
];

export const FLOOR_NUMBERS: FloorNumber[] = [1, 2, 3];

export function bedId(roomNumber: number, label: string): string {
  return `${roomNumber}-${label}`;
}

/** Build the empty structure: 3 floors × 10 rooms × 4 beds = 120 beds. */
export function buildRooms(): Room[] {
  const rooms: Room[] = [];
  for (const floor of FLOOR_NUMBERS) {
    OFFICIAL_ROOM_NUMBERS[floor].forEach((number, position) => {
      const beds: Bed[] = BED_LABELS.map((label) => ({
        id: bedId(number, label),
        roomNumber: number,
        label,
        floor,
        residentId: null,
        mealOn: false,
      }));
      rooms.push({ number, floor, position, beds });
    });
  }
  return rooms;
}

export const ALL_ROOM_NUMBERS: number[] = FLOOR_NUMBERS.flatMap((f) => [...OFFICIAL_ROOM_NUMBERS[f]]);
